.pn-captcha { display: grid; gap: 12px; margin: 16px 0; padding: 16px; border: 1px solid #84918d66; border-radius: 14px; background: #f5f8f6; color: #25372d; box-shadow: 0 5px 18px #14241c12; }
.pn-captcha-heading { display: grid; gap: 5px; }
.pn-captcha-heading strong { font-size: 13px; }
.pn-captcha-heading span { color: #245b47; font-size: 13px; font-weight: 650; }
.pn-captcha-image-row { display: flex; align-items: stretch; gap: 9px; }
.pn-captcha-picture { position: relative; width: min(100%, 320px); aspect-ratio: 9 / 7; min-width: 0; flex: 1; display: grid; place-items: center; overflow: hidden; background: #eef5f1; color: #25372d; border: 2px solid #fff; border-radius: 9px; box-shadow: 0 0 0 1px #acbfb4, 0 3px 10px #17251d16; }
.pn-captcha-select-picture img { display: block; width: 100%; height: 100%; object-fit: cover; filter: contrast(1.2) saturate(1.08); }
.pn-captcha-grid { position: absolute; inset: 0; display: grid; grid-template-columns: repeat(var(--captcha-grid-size, 4), 1fr); grid-template-rows: repeat(var(--captcha-grid-size, 4), 1fr); }
.pn-captcha-grid button { min-width: 0; padding: 0; border: 1px solid #fff; border-radius: 0; background: transparent; cursor: pointer; transition: background .12s, box-shadow .12s; }
.pn-captcha-grid button:hover { background: #ffffff20; }
.pn-captcha-grid button.is-selected { background: #2180ed44; box-shadow: inset 0 0 0 3px #2180ed; }
.pn-captcha-grid button:focus-visible { position: relative; z-index: 1; outline: 3px solid #115fbb; outline-offset: -4px; }
.pn-captcha-refresh { display: grid; place-content: center; gap: 5px; flex: 0 0 68px; border: 1px solid #b5c4bb; border-radius: 9px; background: #fff; color: #245b47; font-size: 25px; cursor: pointer; }
.pn-captcha-refresh span { font-size: 9px; }
.pn-captcha-refresh:disabled, .pn-captcha-grid button:disabled { opacity: .55; cursor: wait; }
.pn-captcha-actions { display: flex; justify-content: space-between; align-items: center; gap: 8px; font-size: 11px; color: #4e6257; }
.pn-captcha-actions button, .pn-captcha p button { padding: 5px 9px; border: 1px solid #84918d55; border-radius: 5px; background: transparent; color: inherit; font: inherit; cursor: pointer; }
.pn-captcha-actions button:disabled { opacity: .45; cursor: default; }
.pn-captcha p { margin: 0; font-size: 12px; }
.pn-captcha--code { gap: 9px; padding: 13px; border-color: #d8e4de; border-radius: 14px; background: linear-gradient(145deg, #fff, #f5f8f6); box-shadow: 0 8px 24px #152b2010; }
.pn-captcha-code-header { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.pn-captcha--code .pn-captcha-heading { min-width: 0; gap: 3px; }
.pn-captcha--code .pn-captcha-heading strong { color: #263a31; font-size: 12px; font-weight: 800; }
.pn-captcha--code .pn-captcha-heading > span { color: #63736a; font-size: 10px; font-weight: 500; line-height: 1.35; }
.pn-captcha-code-row { display: flex; align-items: stretch; gap: 8px; }
.pn-captcha--code .pn-captcha-refresh { display: flex; min-width: 62px; min-height: 58px; flex: 0 0 auto; align-items: center; justify-content: center; flex-direction: column; gap: 3px; padding: 6px; border: 1px solid #cad9d0; border-radius: 9px; color: #267752; background: #fff; font-size: 20px; line-height: 1; transition: background .16s ease, border-color .16s ease, transform .16s ease; }
.pn-captcha--code .pn-captcha-refresh > span:last-child { color: #5d7166; font-size: 8px; font-weight: 600; white-space: nowrap; }
.pn-captcha--code .pn-captcha-refresh:hover:not(:disabled) { transform: translateY(-1px); border-color: #8bc6a5; background: #f4fbf6; }
.pn-captcha--code .pn-captcha-refresh:focus-visible { outline: 2px solid #27845b; outline-offset: 2px; }
.pn-captcha--code .pn-captcha-refresh:disabled { cursor: wait; }
.pn-captcha-code-picture { display: grid; min-width: 0; min-height: 58px; flex: 1; place-items: center; overflow: hidden; border: 1px solid #cbd9d1; border-radius: 9px; background: #eef5f1; }
.pn-captcha-code-picture img { display: block; width: 100%; height: 58px; object-fit: contain; }
.pn-captcha-code-picture > span { color: #6a7971; font-size: 11px; }
.pn-captcha-code-answer { display: grid; gap: 5px; color: #4a5d52; font-size: 10px; font-weight: 700; }
.pn-captcha-code-answer input { box-sizing: border-box; width: 100%; min-height: 40px; padding: 0 11px; border: 1px solid #cbd6d0; border-radius: 8px; color: #24372d; background: #fff; font: inherit; font-size: 12px; font-weight: 600; letter-spacing: .08em; text-transform: uppercase; transition: border-color .16s ease, box-shadow .16s ease; }
.pn-captcha-code-answer input::placeholder { color: #87948d; font-size: 11px; font-weight: 500; letter-spacing: .12em; opacity: 1; }
.pn-captcha-code-answer input:focus { outline: none; border-color: #55a77c; box-shadow: 0 0 0 3px #55a77c20; }
.pn-captcha-code-answer input:disabled { cursor: wait; background: #f3f6f4; }
.pn-captcha--code > p[role="alert"] { color: #a43a32; line-height: 1.5; }
@media (max-width: 420px) {
  .pn-captcha--code { padding: 11px; }
  .pn-captcha--code .pn-captcha-refresh { min-width: 56px; }
}
